const manualChapters=[
  {title:"O mapa da eletricidade",tag:"Começa aqui",text:"Antes das fórmulas, fixa quatro ideias: uma fonte cria tensão, um percurso fechado permite corrente, a carga transforma energia e a proteção limita as consequências de um defeito.",detail:"Imagina a tensão como a diferença que empurra as cargas, a corrente como a quantidade que atravessa o circuito e a resistência como a oposição encontrada. A analogia ajuda a começar, mas a eletricidade não é água: usa-a apenas para perceber a relação entre as grandezas.",points:["Tensão: diferença de potencial, medida em volt (V)","Corrente: movimento de carga, medido em ampere (A)","Resistência: oposição à corrente, medida em ohm (Ω)"],visual:"basics"},
  {title:"Fase, neutro e proteção",tag:"Condutores",text:"Numa alimentação monofásica, L é o condutor ativo, N pertence ao circuito funcional de retorno e PE é o condutor de proteção. PE não deve transportar corrente durante o funcionamento normal.",detail:"As cores ajudam a identificar, mas nunca são uma prova suficiente: instalações antigas, alterações ou erros podem não respeitar a convenção. A função deve ser confirmada pelo esquema, inspeção e procedimentos de verificação adequados. Em Portugal e na harmonização europeia, é comum encontrar castanho na fase, azul no neutro e verde/amarelo na proteção.",points:["L — fase: condutor ativo","N — neutro: condutor do circuito funcional","PE — proteção: caminho previsto para correntes de defeito"],visual:"conductors"},
  {title:"Como nasce um circuito",tag:"Percurso fechado",text:"Fonte, proteção, comando, carga e condutores formam uma cadeia funcional. Um interruptor aberto interrompe o percurso; quando fecha, a corrente pode circular e a carga transforma energia.",detail:"Exemplo: num ponto de luz, a proteção alimenta o circuito, o interruptor comanda o condutor ativo e a lâmpada é a carga. O neutro completa o circuito funcional e o PE protege as massas metálicas quando aplicável. Um circuito final é simplesmente o circuito que alimenta diretamente tomadas, iluminação ou outro equipamento de utilização.",points:["Proteção limita consequências de sobreintensidades","Comando abre ou fecha a alimentação da carga","Carga transforma energia elétrica em luz, calor ou movimento"],visual:"circuit"},
  {title:"Série e paralelo",tag:"Comparação visual",text:"Em série existe um único percurso e a mesma corrente atravessa os elementos. Em paralelo existem vários ramos e a tensão aplicada é comum a cada ramo.",detail:"Nas habitações, as cargas são normalmente ligadas em paralelo para receberem a tensão prevista e poderem funcionar de forma independente. Se uma lâmpada de um ramo for desligada, as outras podem continuar ligadas. Em série, abrir um ponto interrompe o único percurso.",points:["Série: um percurso e corrente comum","Paralelo: vários ramos e tensão comum","Cargas domésticas funcionam sobretudo em paralelo"],visual:"parallel"},
  {title:"Lei de Ohm sem medo",tag:"Cálculo",text:"A relação U = R × I descreve o comportamento de um elemento resistivo. Conhecendo duas grandezas, podes calcular a terceira, desde que uses unidades compatíveis.",detail:"Exemplo resolvido: uma resistência de 46 Ω ligada a 230 V conduz, no modelo simples, I = U ÷ R = 230 ÷ 46 = 5 A. Primeiro escreve os dados, depois escolhe a forma da fórmula, substitui os valores e confirma a unidade. O resultado é um cálculo didático; não autoriza escolher cabos ou proteções sem analisar as restantes condições.",points:["U em volt (V)","I em ampere (A)","R em ohm (Ω)"],visual:"ohm"},
  {title:"Potência e consumo",tag:"Energia",text:"Potência indica a rapidez com que a energia é transformada. Energia consumida depende da potência e do tempo de funcionamento.",detail:"Um equipamento de 1 kW ligado durante 2 horas utiliza 2 kWh. Um equipamento de 2 kW durante 1 hora também utiliza 2 kWh. kW indica potência; kWh indica energia acumulada. Em situações simples, P = U × I ajuda a relacionar potência, tensão e corrente, mas equipamentos reais podem exigir informação adicional.",points:["Potência: watt (W) ou quilowatt (kW)","Energia: quilowatt-hora (kWh)","Energia = potência × tempo"],visual:"power"},
  {title:"Proteções não são todas iguais",tag:"Quadro elétrico",text:"O disjuntor atua contra sobreintensidades; o diferencial deteta um desequilíbrio entre correntes nos condutores ativos. O PE e a ligação à terra integram o sistema de proteção.",detail:"Sobrecarga é corrente excessiva num circuito sem ligação direta de baixa impedância; curto-circuito é uma ligação de impedância muito baixa. Corrente residual é a diferença que indica que parte da corrente seguiu um caminho não previsto. Coordenação significa que condutores, terra e dispositivos devem funcionar em conjunto para desligar nas condições previstas.",points:["Disjuntor: sobrecarga e curto-circuito","Diferencial: desequilíbrio ou corrente residual","PE: caminho de proteção, não substitui o diferencial"],visual:"protection"},
  {title:"Como estudar no Voltz",tag:"Preparação final",text:"Lê o princípio, observa a imagem ou o esquema, explica por palavras tuas e resolve o exemplo antes de responder. Voltar atrás faz parte da aprendizagem.",detail:"Cada desafio tem 10 perguntas. A primeira resposta a cada pergunta conta para a nota e são necessárias 8 respostas certas para desbloquear o nível seguinte. Depois de um erro, recebes a resposta correta e uma explicação; podes repetir com as opções noutra posição, mas o erro continua registado. Os níveis ensinam conceitos e não autorizam trabalhos regulamentados.",points:["10 perguntas por nível, sobre a aula anterior","8 certas à primeira tentativa para avançar","Manual sempre disponível para consulta"],visual:"ready"},
];
